'use strict';
const games=[{id:'neon',name:'Neon Triple',category:'Slots demo',glyph:'7<span>7</span>7',colors:['#234b83','#713c91'],type:'slot',tag:'ORIGINAL'},{id:'emerald',name:'Emerald Dice',category:'Dados demo',glyph:'⚄',colors:['#125849','#1b9380'],type:'dice',tag:'DADOS'},{id:'ocean',name:'Ocean Numbers',category:'Números demo',glyph:'0<span>7</span>',colors:['#17386e','#2179a6'],type:'number',tag:'NÚMEROS'},{id:'aurora',name:'Aurora Triple',category:'Slots demo',glyph:'◆<span>◆</span>◆',colors:['#42376c','#307c89'],type:'slot',tag:'ORIGINAL'},{id:'royal',name:'Royal Dice',category:'Dados demo',glyph:'⚅',colors:['#45386b','#815e9e'],type:'dice',tag:'DADOS'},{id:'mint',name:'Mint Numbers',category:'Números demo',glyph:'2<span>1</span>',colors:['#204746','#478a68'],type:'number',tag:'NÚMEROS'}];
const initial=()=>({name:'',balance:1000,favorites:[],transactions:[],paused:false});let state;try{state=JSON.parse(localStorage.getItem('bluegreen-demo-v1'))||initial();if(!Number.isSafeInteger(state.balance)||state.balance<0||!Array.isArray(state.transactions)||!Array.isArray(state.favorites))state=initial();state.name=typeof state.name==='string'?state.name.slice(0,40):'';state.paused=state.paused===true;state.favorites=state.favorites.filter(id=>games.some(g=>g.id===id));state.transactions=state.transactions.filter(t=>t&&typeof t.id==='string'&&typeof t.date==='string'&&!Number.isNaN(Date.parse(t.date))&&typeof t.type==='string'&&typeof t.detail==='string'&&Number.isSafeInteger(t.amount)).slice(0,500)}catch{state=initial()}let view=['jogos','favoritos','carteira','historico','admin'].includes(window.location.hash.slice(1))?window.location.hash.slice(1):'jogos',filter='Todos',query='',playing=false,activeGame=null;const main=document.querySelector('#main'),modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>new Intl.NumberFormat('pt-BR').format(n)+' cr';const persist=()=>{try{localStorage.setItem('bluegreen-demo-v1',JSON.stringify(state))}catch{toast('O navegador não permitiu salvar. Esta sessão continua funcionando.')}};function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}function updateHeader(){document.querySelector('#balance').textContent=fmt(state.balance);document.querySelector('#profile').textContent=state.name?state.name:'Criar perfil demo'}function tx(type,amount,detail){state.transactions.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),type,amount,detail});state.transactions=state.transactions.slice(0,500);persist();updateHeader()}function open(html){content.innerHTML=html;modal.showModal()}document.querySelector('.close').onclick=()=>{if(!playing)modal.close()};modal.addEventListener('cancel',e=>{if(playing)e.preventDefault()});modal.addEventListener('click',e=>{if(e.target===modal&&!playing)modal.close()});
function table(rows=state.transactions){return rows.length?`<div class="table-wrap"><table><thead><tr><th>DATA / HORA</th><th>MOVIMENTAÇÃO</th><th>DETALHE</th><th>CRÉDITOS</th><th>STATUS</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(new Date(t.date).toLocaleString('pt-BR'))}</td><td>${esc(t.type)}</td><td>${esc(t.detail)}</td><td class="${t.amount>0?'green':''}">${t.amount>0?'+':''}${fmt(t.amount)}</td><td><span class="badge">Demo concluída</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>Nenhuma movimentação ainda</b>Jogue uma rodada ou adicione créditos de teste para começar.</div>`}
function card(g){return `<article class="game"><div class="game-art" style="--art1:${g.colors[0]};--art2:${g.colors[1]}"><span class="tag">${g.tag}</span><button class="favorite ${state.favorites.includes(g.id)?'on':''}" data-fav="${g.id}" aria-label="${state.favorites.includes(g.id)?'Remover':'Adicionar'} ${g.name} dos favoritos" aria-pressed="${state.favorites.includes(g.id)}">${state.favorites.includes(g.id)?'♥':'♡'}</button><div class="glyph" aria-hidden="true">${g.glyph}</div></div><div class="game-info"><h3>${g.name}</h3><div class="game-meta"><span>${g.category}</span><span>BlueGreen Originals</span></div><button data-game="${g.id}">Jogar demonstração</button></div></article>`}
function render(){updateHeader();const labels={jogos:'Jogos',favoritos:'Meus favoritos',carteira:'Minha carteira',historico:'Histórico',admin:'Painel de gestão'};document.querySelector('#page-label').textContent=labels[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='jogos'||view==='favoritos'){main.innerHTML=`${view==='jogos'?`<section class="hero"><div><div class="eyebrow">BLUEGREEN ORIGINALS</div><h1>Entre no jogo.<br>Explore o seu ritmo.</h1><p>Conheça nossa seleção de jogos originais com 1.000 créditos de demonstração para começar.</p><div class="hero-actions"><button class="primary" data-game="neon">Experimentar Neon Triple</button><button data-view="carteira">Ver minha carteira</button></div></div><div class="hero-visual-wrap"><div class="hero-visual" aria-hidden="true"><div class="tile">7</div><div class="tile">7</div><div class="tile">7</div></div><div class="hero-visual-label">NEON TRIPLE · DEMO</div></div></section>`:''}<div class="section-head"><div><h2>${view==='favoritos'?'Seus favoritos':'Escolha seu próximo jogo'}</h2><p>Jogos de teste · Sem dinheiro real</p></div><input class="search" id="search" placeholder="Buscar jogo..." aria-label="Buscar jogo" value="${esc(query)}"></div><div class="filters">${['Todos','Slots demo','Dados demo','Números demo'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f}</button>`).join('')}</div><div class="grid" id="game-grid"></div><div class="strip"><div><h3>Seu espaço para conhecer a plataforma</h3><p>Adicione créditos fictícios e acompanhe todas as suas rodadas.</p></div><button data-view="historico">Ver movimentações</button></div>`;renderGames();document.querySelector('#search').oninput=e=>{query=e.target.value;renderGames()}}else if(view==='carteira'){main.innerHTML=`<div class="eyebrow">SEU SALDO</div><h1>Minha carteira</h1><p>Créditos exclusivos para esta demonstração, sem valor em dinheiro.</p><div class="stats"><div class="stat"><small>Saldo disponível</small><strong class="green">${fmt(state.balance)}</strong></div><div class="stat"><small>Créditos adicionados</small><strong>${fmt(state.transactions.filter(t=>t.type==='Recarga demo').reduce((n,t)=>n+t.amount,1000))}</strong></div><div class="stat"><small>Rodadas realizadas</small><strong>${state.transactions.filter(t=>t.type==='Rodada').length}</strong></div></div><div class="panel"><h2>Teste o fluxo da carteira</h2><p>Adicione créditos de demonstração. Depósitos Pix e saques reais ainda não estão integrados.</p><div class="actions"><button class="primary" id="topup">Adicionar 1.000 créditos</button><button id="withdraw">Simular retirada</button></div></div><div class="panel"><div class="section-head"><h2>Últimas movimentações</h2><button data-view="historico">Ver todas</button></div>${table(state.transactions.slice(0,8))}</div>`;document.querySelector('#topup').onclick=()=>{if(state.balance>999000)return toast('Limite de 1 milhão de créditos demo.');state.balance+=1000;tx('Recarga demo',1000,'Recarga fictícia');render();toast('1.000 créditos de demonstração adicionados')};document.querySelector('#withdraw').onclick=()=>{open(`<div class="eyebrow">SIMULAÇÃO</div><h2>Retirar créditos demo</h2><p>Este teste reduz o saldo fictício. Nenhum pagamento será enviado.</p><form id="withdraw-form"><label for="amount">Quantidade de créditos</label><input id="amount" type="number" min="1" max="${state.balance}" step="1" required><button class="primary">Confirmar simulação</button></form>`);document.querySelector('#withdraw-form').onsubmit=e=>{e.preventDefault();const n=Number(document.querySelector('#amount').value);if(!Number.isSafeInteger(n)||n<1||n>state.balance)return toast('Informe um valor dentro do saldo disponível.');state.balance-=n;tx('Retirada demo',-n,'Sem transferência financeira');modal.close();render();toast('Retirada fictícia concluída')}}}else if(view==='historico'){main.innerHTML=`<div class="eyebrow">ATIVIDADE</div><h1>Histórico de movimentações</h1><p>Consulte os créditos adicionados, rodadas e resultados neste aparelho.</p><div class="panel">${table()}</div>`}else{const bets=state.transactions.filter(t=>t.type==='Rodada'),wins=state.transactions.filter(t=>t.type==='Resultado');main.innerHTML=`<div class="eyebrow">GESTÃO · DEMONSTRAÇÃO</div><h1>Visão geral da operação</h1><p>Painel de teste do perfil deste aparelho. O acesso administrativo de produção ainda não está conectado.</p><div class="stats"><div class="stat"><small>Perfis neste aparelho</small><strong>${state.name?1:0}</strong></div><div class="stat"><small>Créditos em rodadas</small><strong>${fmt(-bets.reduce((n,t)=>n+t.amount,0))}</strong></div><div class="stat"><small>Créditos em resultados</small><strong class="green">${fmt(wins.reduce((n,t)=>n+t.amount,0))}</strong></div></div><div class="settings"><section class="panel"><h2>Perfil demonstrativo</h2><p><b>${esc(state.name||'Visitante')}</b></p><p>Saldo: <span class="green">${fmt(state.balance)}</span></p><span class="badge">Dados locais de teste</span></section><section class="panel"><h2>Disponibilidade dos jogos</h2><p>Pause os jogos de demonstração para testar o estado de manutenção.</p><button id="pause">${state.paused?'Reativar jogos':'Pausar jogos'}</button></section></div><section class="panel"><h2>Preparar uma nova apresentação</h2><p>Reinicie este aparelho com 1.000 créditos e histórico vazio. Seus favoritos também serão removidos.</p><button id="reset-demo">Reiniciar demonstração</button></section><section class="panel"><h2>Integrações de produção</h2><p>Cadastro e login conectados ao Supabase. Provedores de jogos e gateway Pix ainda não conectados. Este painel continua sendo uma demonstração local.</p></section><section class="panel"><div class="section-head"><h2>Registro de movimentações</h2><button id="export">Exportar CSV</button></div>${table(state.transactions.slice(0,20))}</section>`;document.querySelector('#reset-demo').onclick=()=>{open('<h2>Reiniciar demonstração?</h2><p>O perfil, saldo, favoritos e histórico de teste deste navegador serão apagados. Esta ação não altera dados de outros aparelhos.</p><div class="actions"><button id="cancel-reset">Cancelar</button><button id="confirm-reset" class="primary">Reiniciar teste</button></div>');document.querySelector('#cancel-reset').onclick=()=>modal.close();document.querySelector('#confirm-reset').onclick=()=>{state=initial();persist();modal.close();render();toast('Demonstração reiniciada com 1.000 créditos')}};document.querySelector('#pause').onclick=()=>{state.paused=!state.paused;persist();render();toast(state.paused?'Jogos demo pausados':'Jogos demo reativados')};document.querySelector('#export').onclick=()=>{const lines=[['Data','Tipo','Detalhe','Creditos'],...state.transactions.map(t=>[t.date,t.type,t.detail,t.amount])];const csv='\uFEFF'+lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='bluegreen-movimentacoes-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}bind()}
function renderGames(){const list=games.filter(g=>(view!=='favoritos'||state.favorites.includes(g.id))&&(filter==='Todos'||g.category===filter)&&g.name.toLowerCase().includes(query.toLowerCase()));document.querySelector('#game-grid').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><b>${view==='favoritos'?'Nenhum favorito encontrado':'Nenhum jogo encontrado'}</b>${view==='favoritos'?'Toque no coração de um jogo para salvá-lo.':'Experimente outro nome ou categoria.'}</div>`;bind()}
function navigate(v){if(!['jogos','favoritos','carteira','historico','admin'].includes(v))throw new Error('Área inválida');view=v;window.history.replaceState(null,'','#'+v);query='';filter='Todos';render();window.scrollTo({top:0,behavior:'smooth'});return {area:view,saldo:state.balance}}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{const id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();renderGames()})}
function random(n){const arr=new Uint32Array(1);const limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(arr)}while(arr[0]>=limit);return arr[0]%n}
function startGame(id){const g=games.find(g=>g.id===id);if(!g)throw new Error('Jogo inválido');if(state.paused){toast('Jogos em manutenção nesta demonstração.');return {status:'pausado'}}activeGame=g;const rules=g.type==='slot'?'Três símbolos iguais: 10× os créditos da rodada. Dois iguais: 2×. São 4 símbolos possíveis, com chances iguais.':g.type==='dice'?'Escolha um número de 1 a 6. Se o dado mostrar o número escolhido, o retorno é 5×. Chance de acerto: 1 em 6.':'Escolha um número de 0 a 9. Se acertar, o retorno é 9×. Chance de acerto: 1 em 10.';open(`<div class="eyebrow">BLUEGREEN ORIGINALS · DEMO</div><h2>${g.name}</h2><p>${rules}</p><div class="reels">${g.type==='slot'?'<div class="reel">7</div><div class="reel">7</div><div class="reel">7</div>':'<div class="reel">?</div>'}</div><div class="result" id="result" role="status" aria-live="polite">Pronto para a primeira rodada?</div><label for="stake">Créditos por rodada</label><div class="game-controls"><select id="stake"><option value="10">10 créditos</option><option value="25">25 créditos</option><option value="50">50 créditos</option></select>${g.type!=='slot'?`<select id="pick" aria-label="Número escolhido">${Array.from({length:g.type==='dice'?6:10},(_,i)=>`<option value="${i+(g.type==='dice'?1:0)}">Número ${i+(g.type==='dice'?1:0)}</option>`).join('')}</select>`:''}</div><button class="primary" id="play">Jogar rodada demo</button><p class="note">Saldo: <span id="game-balance">${fmt(state.balance)}</span> · Retorno inclui os créditos da rodada. Resultados aleatórios, sem ajuste por jogador.</p>`);document.querySelector('#play').onclick=play;return {jogo:g.name,status:'aberto'}}
async function play(){if(playing)return;const g=activeGame,stake=Number(document.querySelector('#stake').value),pick=Number(document.querySelector('#pick')?.value);if(![10,25,50].includes(stake))return;if(state.balance<stake)return toast('Saldo insuficiente. Adicione créditos demo na carteira.');if(state.paused)return toast('Jogos pausados.');playing=true;state.balance-=stake;tx('Rodada',-stake,g.name);const btn=document.querySelector('#play');btn.disabled=true;btn.textContent='Rodada em andamento…';document.querySelector('#stake').disabled=true;if(document.querySelector('#pick'))document.querySelector('#pick').disabled=true;const values=g.type==='slot'?[random(4),random(4),random(4)]:[random(g.type==='dice'?6:10)+(g.type==='dice'?1:0)];const symbols=['7','◆','●','✦'];const multiplier=g.type==='slot'?(new Set(values).size===1?10:new Set(values).size===2?2:0):(values[0]===pick?(g.type==='dice'?5:9):0);await new Promise(r=>setTimeout(r,650));document.querySelectorAll('.reel').forEach((e,i)=>e.textContent=g.type==='slot'?symbols[values[i]]:values[i]);const payout=stake*multiplier;state.balance+=payout;tx('Resultado',payout,`${g.name}: ${values.map(v=>g.type==='slot'?symbols[v]:v).join(' / ')}`);document.querySelector('#result').textContent=payout?`Retorno de ${fmt(payout)}. Resultado líquido: ${payout-stake>=0?'+':''}${fmt(payout-stake)}.`:'Sem retorno nesta rodada.';document.querySelector('#game-balance').textContent=fmt(state.balance);btn.disabled=false;btn.textContent='Jogar outra rodada';document.querySelector('#stake').disabled=false;if(document.querySelector('#pick'))document.querySelector('#pick').disabled=false;playing=false}
document.querySelector('#profile').onclick=()=>{open(`<div class="eyebrow">SEU ESPAÇO</div><h2>${state.name?'Editar perfil demo':'Criar perfil de demonstração'}</h2><p>Salvo apenas neste navegador. Não é uma conta de produção e não solicita senha ou dados bancários.</p><form id="profile-form"><label for="name">Como podemos chamar você?</label><input id="name" maxlength="40" autocomplete="given-name" required value="${esc(state.name)}"><button class="primary">Salvar perfil demo</button></form>`);document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#name').value.trim();if(!name)return;state.name=name;persist();modal.close();render();toast('Perfil de demonstração salvo')}};document.querySelector('#info').onclick=()=>open('<div class="eyebrow">BLUEGREEN PLAY</div><h2>Uma primeira versão para explorar</h2><p>Seis jogos próprios de demonstração, favoritos, perfil local, carteira fictícia, histórico e painel de gestão de teste.</p><p>Os dados ficam neste navegador. O painel é aberto para avaliação, sem autenticação administrativa. Não há jogos de provedores externos, dinheiro real ou Pix integrado.</p><p>Para uma operação real, serão necessárias as integrações contratadas, autenticação segura e validação dos requisitos aplicáveis.</p>');window.addEventListener('hashchange',()=>{const v=window.location.hash.slice(1);if(['jogos','favoritos','carteira','historico','admin'].includes(v))navigate(v)});render();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_demo_wallet',description:'Consulta saldo fictício e movimentações deste navegador.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({saldo:state.balance,movimentacoes:state.transactions.length,ficticio:true})},{name:'navigate_demo_area',description:'Abre uma área visível da demonstração BlueGreen Play.',inputSchema:{type:'object',properties:{area:{type:'string',enum:['jogos','favoritos','carteira','historico','admin']}},required:['area'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>navigate(input.area)}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
